{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In healthy volunteers, chrysin, a related hydroxyflavone, showed oral bioavailability less than 1% at 400 mg, demonstrating very poor systemic exposure for a polyphenolic benzopyrone-like compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Predicted absolute oral bioavailability of chrysin in humans was 0.003–0.02%, directly far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Peonidin glycosides in humans had fractional systemic bioavailability of 0.32±0.05%, showing that methoxy/hydroxy polyphenolic glycosides are very poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Petunidin glycosides in humans had systemic bioavailability of 0.20±0.02%, again far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Curcumin, a methoxyphenol-containing polyphenol, has repeatedly shown low oral bioavailability in humans after oral administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Flavonolignans in patients had very high apparent oral clearances (151–2016 L/h), indicating very low oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite favorable physicochemical priors, high-transfer human pharmacokinetic evidence from structurally related methoxy/hydroxy polyphenolic compounds (flavones, anthocyanins, curcumin, flavonolignans) consistently shows oral bioavailability far below 20%, often <1%. The query's small coumarin scaffold may improve absorption, but the weight of direct experimental evidence supports low oral bioavailability.",
  "evidence_gaps": [
    "No direct human or animal pharmacokinetic data for this exact coumarin.",
    "Extrapolation from flavonoids, anthocyanins, curcumin, and flavonolignans rather than from coumarins.",
    "Possible first-pass conjugation of the phenol group is inferred but not directly measured for the query.",
    "No intravenous/oral AUC comparison is available for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

